<script setup>
import {ref,onMounted,watch} from 'vue';import PageHeader from '../../components/common/PageHeader.vue';import StatusView from '../../components/common/StatusView.vue';import {getCases} from '../../api/catalog.js'
const space=ref(''),style=ref(''),items=ref([]),loading=ref(true);async function load(){loading.value=true;items.value=(await getCases({space:space.value,style:style.value})).data;loading.value=false}onMounted(load);watch([space,style],load)
</script>
<template><div class="page-shell"><div class="container"><PageHeader title="案例灵感" description="从真实居住方式中，寻找属于您的空间答案。" :breadcrumbs="['首页','案例灵感']"/><div class="filter-bar"><el-select v-model="space" placeholder="全部空间" clearable style="width:150px"><el-option v-for="x in ['厨房','全屋','衣帽间','餐厅']" :key="x" :label="x" :value="x"/></el-select><el-select v-model="style" placeholder="全部风格" clearable style="width:150px"><el-option v-for="x in ['现代欧式','法式简约']" :key="x" :label="x" :value="x"/></el-select></div><StatusView v-if="loading" type="loading"/><div v-else class="editorial-grid case-grid"><router-link v-for="item in items" :key="item.id" :to="`/cases/${item.id}`" class="editorial-card"><div class="editorial-card__image"><img :src="item.image" :alt="item.name"></div><h3>{{item.name}}</h3><p class="muted">{{item.area}} · {{item.space}} · {{item.style}}</p></router-link></div></div></div></template>
<style scoped>.case-grid{padding-top:28px}.case-grid>*:first-child{grid-column:span 2}.case-grid>*:first-child .editorial-card__image{height:360px}@media(max-width:767px){.case-grid>*:first-child{grid-column:auto}.case-grid>*:first-child .editorial-card__image{height:260px}}</style>
